package main
import ("fmt"; "time"; r "gopurs/output/gopurs_runtime")
var sink int64
//go:noinline
func opaque(n int64) int64 { return n }
func loop(n int64) int64 { ref:=r.NewSTRef(r.Int(0)); for left:=n;left>0;left=r.IntSub(left,1) { r.WriteSTRef(ref,r.Int(r.IntAdd(r.ReadSTRef(ref).IntVal,1))) }; return r.ReadSTRef(ref).IntVal }
func folded(n int64) int64 { v:=int64(0);if n>0 {v=r.IntAdd(v,n)};return v }
func main(){for _,n:=range []int64{-7,0,1,17,10000}{if loop(opaque(n))!=folded(opaque(n)){panic(n)}};for _,f:=range []func(int64)int64{loop,folded}{s:=time.Now();for k:=0;k<10000;k++{sink=f(opaque(10000))};fmt.Println(time.Since(s),sink)}}

